-- Generated by scripts/db/generate-baseline.py from live-catalog.json. Do not edit by hand.
create or replace view public.gl_accounts as
 SELECT id,
    code,
    name,
        CASE
            WHEN (account_type = 'income'::text) THEN 'revenue'::text
            ELSE account_type
        END AS type,
    is_active
   FROM public.chart_of_accounts;

create or replace view public.gl_orphaned_document_entries as
 SELECT id,
    entry_no,
    entry_date,
    source_type,
    COALESCE(document_id, source_id) AS document_id,
    memo,
    ( SELECT COALESCE(sum(l.debit), (0)::numeric) AS "coalesce"
           FROM public.journal_entry_lines l
          WHERE (l.journal_entry_id = je.id)) AS total_debit
   FROM public.journal_entries je
  WHERE ((COALESCE(document_id, source_id) IS NOT NULL) AND (reversal_of IS NULL) AND (reversed_by IS NULL) AND ((source_type ~~* '%invoice%'::text) OR (source_type ~~* '%sale%'::text) OR (source_type ~~* '%purchase%'::text)) AND (NOT (EXISTS ( SELECT 1
           FROM public.sales s
          WHERE (s.id = COALESCE(je.document_id, je.source_id))))) AND (NOT (EXISTS ( SELECT 1
           FROM public.purchases p
          WHERE (p.id = COALESCE(je.document_id, je.source_id))))));

create or replace view public.journal_lines as
 SELECT id,
    journal_entry_id AS entry_id,
    coa_id AS account_id,
    partner_id,
    debit,
    credit
   FROM public.journal_entry_lines jel;

create or replace view public.product_category_paths with (security_invoker=true) as
 SELECT p.id AS product_id,
    NULLIF(btrim(COALESCE(
        CASE
            WHEN (lc.parent_id IS NOT NULL) THEN pc.name
            ELSE lc.name
        END, p.category)), ''::text) AS category_name,
    NULLIF(btrim(COALESCE(
        CASE
            WHEN (lc.parent_id IS NOT NULL) THEN lc.name
            ELSE NULL::text
        END, sc.name, p.subcategory)), ''::text) AS subcategory_name
   FROM (((public.products p
     LEFT JOIN public.categories lc ON ((lc.id = p.category_id)))
     LEFT JOIN public.categories pc ON ((pc.id = lc.parent_id)))
     LEFT JOIN public.categories sc ON ((sc.id = p.sub_category_id)));
